HOW = ["Intuition", "How it works", "In practice"]


def _r(key, situation, q, analogy, picture, caption, play, checklist, trap_title, trap_html):
    plan = _plan(situation, q, analogy, picture, caption, ("c4", play[0], play[1]), ["c2", "c3"], ["c5"], [], ["src"], checklist, tabs=HOW, trap_title=trap_title, trap_html=trap_html)
    return f"ai-engineering/{key}", plan


